import json, os, re
from pathlib import Path

def flatten(obj, prefix=''):
    out={}
    if isinstance(obj, dict):
        for k,v in obj.items():
            nk = f"{prefix}.{k}" if prefix else str(k)
            out.update(flatten(v, nk))
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            nk = f"{prefix}[{i}]"
            out.update(flatten(v, nk))
    else:
        out[prefix]=obj
    return out

# Load JSON
with open('/root/supplier_contact.json','r',encoding='utf-8') as f:
    data=json.load(f)
flat=flatten(data)

# Build replacement map: include both raw keys and dotted keys (flat already raw for top-level)
replacements={k: ('' if v is None else str(v)) for k,v in flat.items() if k}

work_dir='/tmp/hwpx_work'
modified_files=[]

# helper to replace potentially-fragmented placeholders
TAG_RE = re.compile(r'<[^>]+>')

def replace_fragmented(content):
    # matches {{ ... }} even if inside has tags/newlines
    pattern = re.compile(r'\{\{(.*?)\}\}', re.DOTALL)
    def sub(m):
        inner=m.group(1)
        inner_clean=TAG_RE.sub('', inner).strip()
        if inner_clean in replacements:
            return replacements[inner_clean]
        return m.group(0)
    return pattern.sub(sub, content)

# Process files
for root, _, files in os.walk(work_dir):
    for fname in files:
        if not fname.endswith(('.xml','.rels','.hpf')):
            continue
        fpath=os.path.join(root,fname)
        with open(fpath,'r',encoding='utf-8') as f:
            content=f.read()
        original=content

        # direct replacements {{key}}
        for key, value in replacements.items():
            content = content.replace('{{'+key+'}}', value)

        # fragmented replacements
        content = replace_fragmented(content)

        if content != original:
            # Remove lineSegArray / linesegarray blocks (case-insensitive) where modified
            content = re.sub(r'<hp:lineSegArray>.*?</hp:lineSegArray>', '', content, flags=re.DOTALL)
            content = re.sub(r'<hp:linesegarray>.*?</hp:linesegarray>', '', content, flags=re.DOTALL|re.IGNORECASE)

            with open(fpath,'w',encoding='utf-8') as f:
                f.write(content)
            modified_files.append(os.path.relpath(fpath, work_dir))

print('Modified files:', modified_files)
# Verify no placeholders remain
remaining=[]
for root, _, files in os.walk(work_dir):
    for fname in files:
        if fname.endswith(('.xml','.rels','.hpf')):
            p=os.path.join(root,fname)
            with open(p,'r',encoding='utf-8') as f:
                t=f.read()
            if '{{' in t:
                remaining.append(os.path.relpath(p, work_dir))
print('Files still containing {{ :', remaining)
